WITH valid AS (SELECT *, ROUND(units, 0) AS units_rounded FROM store_sales WHERE store_id IN (1, 2, 5)), valid_store_sales AS (SELECT *, DATE_TRUNC('MONTH', sale_date) AS sale_date_period, LEAST(units, units_rounded) AS least_units_units_rounded FROM valid WHERE sale_date >= TO_DATE('2023-08-21') AND units <= 22), valid_store_sales_2 AS (SELECT *, CAST(units_rounded AS INT) AS units_rounded_int FROM valid_store_sales WHERE sale_date >= DATE '2023-03-31'), with_gaps AS (SELECT *, CASE WHEN sale_date_period - LAG(sale_date_period) OVER (PARTITION BY product_id ORDER BY sale_date_period ASC, id ASC) > INTERVAL '60' DAY THEN 1 ELSE 0 END AS is_new_burst FROM valid_store_sales_2), islands AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY product_id ORDER BY sale_date_period ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT id, store_id, product_id, sale_date, units, revenue, units_rounded_int, is_new_burst FROM islands ORDER BY product_id DESC NULLS LAST;
